//! `agent-worker install <uuid> --server <address>`: what the one-line command runs after it has downloaded this program.
//!
//! The uuid is the install's id, generated by the server when the form was saved (it becomes this worker's id). The program
//! checks in with the server, proves it can reach it, claims the link with a secret generated on this PC and receives the
//! saved settings. A second PC running the same command is refused. Once the server accepts the claim, a new link can replace
//! the local identity in the same home: the installer stops and removes only the old local startup entry, preserves adapter
//! packages and local data, and restores the old configuration and service if registration is refused. It never unregisters
//! the old Fleet identity. Progress goes to the server so the Fleet tab can show each step and the reason for a failure.
use crate::config::{self, default_config, Home};
use crate::ctl::local_health;
use crate::svc::{self, Kind, Svc};
use crate::util::{atomic_json, now_unix};
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use serde_json::{json, Value};
use std::path::PathBuf;
use std::time::{Duration, Instant};

pub struct Options {
    pub uuid: String,
    pub server: String,
    pub port: u16,
    pub no_service: bool,
}

/// What the form saved, as the server hands it over.
pub struct Settings {
    pub name: String,
    pub slots: u64,
    /// "logon", "boot" or "none": when the worker starts by itself
    pub autostart: String,
    /// restart the worker if it crashes or is killed
    pub auto_restart: bool,
}

fn origin(options: &Options) -> String {
    options.server.trim_end_matches('/').to_string()
}

async fn report(options: &Options, step: &str, state: &str, message: &str) {
    let _ = reqwest::Client::new()
        .post(format!(
            "{}/install/{}/progress",
            origin(options),
            options.uuid
        ))
        .json(&json!({"step": step, "state": state, "message": message}))
        .timeout(Duration::from_secs(10))
        .send()
        .await;
}

pub fn default_home() -> PathBuf {
    if cfg!(windows) {
        PathBuf::from(std::env::var("LOCALAPPDATA").unwrap_or_default()).join("AgentWorker")
    } else {
        PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".agent-worker")
    }
}

/// Locate an installation or startup entry on this PC.
pub fn existing_install(home: &Home) -> Option<String> {
    for candidate in [home.0.clone(), default_home()] {
        if candidate.join("installed.json").exists() || candidate.join("worker.json").exists() {
            return Some(candidate.display().to_string());
        }
    }
    // Isolate CLI integration tests from real machine startup entries.
    if std::env::var_os("AGENT_WORKER_TEST_FAST").is_some() {
        return None;
    }
    if cfg!(windows) {
        if let Ok((0, out, _)) = svc::run("schtasks", &["/Query", "/FO", "CSV", "/NH"]) {
            if let Some(line) = out.lines().find(|l| l.contains("AgentWorker-")) {
                return Some(format!(
                    "scheduled task {}",
                    line.split(',')
                        .next()
                        .unwrap_or("")
                        .trim_matches('"')
                        .trim_start_matches('\\')
                ));
            }
        }
    } else {
        let home_dir = std::env::var("HOME").unwrap_or_default();
        for (dir, ext) in [
            (".config/systemd/user", "service"),
            ("Library/LaunchAgents", "plist"),
        ] {
            if let Ok(entries) = std::fs::read_dir(PathBuf::from(&home_dir).join(dir)) {
                for entry in entries.flatten() {
                    let name = entry.file_name().to_string_lossy().to_string();
                    if name.starts_with("agent-worker-") && name.ends_with(ext) {
                        return Some(entry.path().display().to_string());
                    }
                }
            }
        }
    }
    None
}
/// A stable secret for link retries. Persistence is separate so rejected links do not touch the install home.

fn claim_secret(home: &Home) -> Result<String, String> {
    if let Ok(existing) = std::fs::read_to_string(home.file("claim")) {
        if existing.trim().len() >= 20 {
            return Ok(existing.trim().to_string());
        }
    }
    let mut raw = uuid::Uuid::new_v4().as_bytes().to_vec();
    raw.extend(uuid::Uuid::new_v4().as_bytes());
    Ok(URL_SAFE_NO_PAD.encode(raw))
}

fn save_claim_secret(home: &Home, secret: &str) -> Result<(), String> {
    std::fs::create_dir_all(&home.0)
        .map_err(|e| format!("Could not create {}: {e}", home.0.display()))?;
    crate::util::atomic_write(&home.file("claim"), secret.as_bytes())
        .map_err(|e| format!("Could not save the claim secret: {e}"))
}

/// Say what is wrong when the server cannot be reached, in words that point at the fix.
fn explain_network(server: &str, error: &reqwest::Error) -> String {
    let mut chain = String::new();
    let mut source: Option<&dyn std::error::Error> = Some(error);
    while let Some(e) = source {
        chain.push_str(&format!("{e} | "));
        source = e.source();
    }
    let lower = chain.to_lowercase();
    let host = reqwest::Url::parse(server)
        .ok()
        .and_then(|u| u.host_str().map(String::from))
        .unwrap_or_else(|| server.to_string());
    let why = if error.is_timeout() || lower.contains("timed out") {
        format!("{server} did not answer in time. Check that the address is right, that this PC can route to it (VPN, network) and that no firewall drops the traffic.")
    } else if lower.contains("dns")
        || lower.contains("lookup")
        || lower.contains("no such host")
        || lower.contains("name or service not known")
        || lower.contains("not known")
    {
        format!("the name {host} does not resolve on this PC. Use an address this PC can reach: set the form's address field to an IP or a name this PC knows, then create a new link.")
    } else if lower.contains("refused") {
        format!("{server} refused the connection. The board is not running there, or it listens on another port, or a firewall rejects this PC.")
    } else if lower.contains("certificate")
        || lower.contains("tls")
        || lower.contains("ssl")
        || lower.contains("handshake")
    {
        format!("the secure connection to {server} failed ({}). This PC does not trust the server's certificate, or the address uses https where the server speaks http (or the reverse).", chain.split(" | ").next().unwrap_or(""))
    } else if lower.contains("unreachable") || lower.contains("no route") {
        format!("there is no network route to {server} from this PC.")
    } else {
        format!("{} ({})", chain.trim_end_matches(" | "), server)
    };
    format!("Cannot reach the server: {why}")
}

/// Check in with the server: proves the PC can reach it, claims the link and returns what the form saved.
async fn claim(options: &Options, secret: &str) -> Result<Value, String> {
    let body = json!({"claim": secret, "host_os": config::os_name(), "hostname": crate::sysmetrics::host_name().unwrap_or_default()});
    let response = reqwest::Client::new()
        .post(format!(
            "{}/install/{}/claim",
            origin(options),
            options.uuid
        ))
        .json(&body)
        .timeout(Duration::from_secs(20))
        .send()
        .await
        .map_err(|e| explain_network(&options.server, &e))?;
    let status = response.status().as_u16();
    let text = response.text().await.unwrap_or_default();
    let parsed: Option<Value> = serde_json::from_str(&text).ok();
    match (status, parsed) {
        (200, Some(v)) if v["ok"] == true => Ok(v),
        (404, _) => Err("This install link is unknown, expired or already used. Create a new one in the Fleet tab and paste its command.".into()),
        (429, _) => Err("Too many wrong install links came from this PC; wait ten minutes or create a new link.".into()),
        (_, Some(v)) if v["error"].is_string() => Err(v["error"].as_str().unwrap().to_string()),
        (200, _) => Err(format!("{} answered, but not like an agent orchestration server. Check the address (it should be the board's address).", options.server)),
        (s, _) => Err(format!("The server answered HTTP {s}{}. If this is a 502 or 503 the board is running but its relay service is not: start the flow host on the coordinator.", if text.is_empty() { String::new() } else { format!(": {}", text.chars().take(200).collect::<String>()) })),
    }
}

/// Put this program in the install folder (the one-line command runs it from a temporary download).
fn install_self(home: &Home) -> Result<Option<PathBuf>, String> {
    let me = std::env::current_exe().map_err(|e| e.to_string())?;
    let target = home.exe();
    if me.canonicalize().ok() == target.canonicalize().ok() && target.exists() {
        return Ok(None);
    }
    std::fs::create_dir_all(&home.0)
        .map_err(|e| format!("Could not create {}: {e}", home.0.display()))?;
    let part = home.file(&format!("{}.part", Home::exe_name()));
    let replacement = (|| -> Result<(), String> {
        std::fs::copy(&me, &part)
            .map_err(|e| format!("Could not copy the worker to {}: {e}", home.0.display()))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&part, std::fs::Permissions::from_mode(0o755))
                .map_err(|e| e.to_string())?;
        }
        #[cfg(windows)]
        if target.exists() {
            std::fs::remove_file(&target).map_err(|e| {
                format!("Could not replace the worker in {}: {e}", home.0.display())
            })?;
        }
        std::fs::rename(&part, &target).map_err(|e| e.to_string())?;
        Ok(())
    })();
    if let Err(error) = replacement {
        let _ = std::fs::remove_file(&part);
        return Err(error);
    }
    Ok(Some(me))
}

fn in_temp_dir(path: &std::path::Path) -> bool {
    let canon = |p: &std::path::Path| std::fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
    canon(path).starts_with(canon(&std::env::temp_dir()))
}

/// Remove the temporary download once the install is done (Windows cannot delete a running program, so a helper does it).
fn remove_download(path: PathBuf) {
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        let _ = std::process::Command::new("cmd")
            .raw_arg(format!(
                "/c ping -n 4 127.0.0.1 >nul & del /f /q \"{}\"",
                path.display()
            ))
            .creation_flags(
                crate::procutil::DETACHED_PROCESS
                    | crate::procutil::CREATE_NEW_PROCESS_GROUP
                    | crate::procutil::CREATE_NO_WINDOW,
            )
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn();
    }
    #[cfg(not(windows))]
    {
        let _ = std::fs::remove_file(path);
    }
}

/// Windows: remember the user's profile folders and PATH. A worker started at boot runs without the user's environment
/// (their PATH, where Codex, Claude Code and npm tools live, and their profile folders), so `run` restores it from here.
fn capture_profile(worker: &mut Value) {
    if cfg!(windows) {
        let mut profile = serde_json::Map::new();
        for key in [
            "PATH",
            "USERPROFILE",
            "APPDATA",
            "LOCALAPPDATA",
            "HOMEDRIVE",
            "HOMEPATH",
            "USERNAME",
            "USERDOMAIN",
            "TEMP",
            "TMP",
        ] {
            if let Ok(value) = std::env::var(key) {
                profile.insert(key.into(), json!(value));
            }
        }
        worker["profile"] = Value::Object(profile);
    }
}

fn restrict_token(path: &std::path::Path) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))
            .map_err(|e| e.to_string())
    }
    #[cfg(windows)]
    {
        let user = svc::run("whoami", &[])
            .map_err(|e| e.to_string())?
            .1
            .trim()
            .to_string();
        let (code, _, err) = svc::run(
            "icacls",
            &[
                &path.to_string_lossy(),
                "/inheritance:r",
                "/grant:r",
                &format!("{user}:(R,W)"),
            ],
        )
        .map_err(|e| e.to_string())?;
        if code == 0 {
            Ok(())
        } else {
            Err(format!(
                "Could not restrict the token file to this user: {}",
                err.trim()
            ))
        }
    }
}

fn install_cli(home: &Home, config: &mut Value) {
    #[cfg(windows)]
    {
        let entry = home.0.display().to_string();
        let script = format!("$e = [Environment]::GetEnvironmentVariable('Path','User'); $parts = if ($e) {{ $e -split ';' }} else {{ @() }}; if ($parts -notcontains '{0}') {{ [Environment]::SetEnvironmentVariable('Path', (($parts + '{0}') -join ';'), 'User') }}", entry.replace('\'', "''"));
        let _ = svc::run(
            "powershell",
            &["-NoProfile", "-NonInteractive", "-Command", &script],
        );
        config["path_entry"] = json!(entry);
    }
    #[cfg(unix)]
    {
        let link = PathBuf::from(std::env::var("HOME").unwrap_or_default())
            .join(".local/bin/agent-worker");
        let _ = std::fs::create_dir_all(link.parent().unwrap());
        let _ = std::fs::remove_file(&link);
        if std::os::unix::fs::symlink(home.exe(), &link).is_ok() {
            config["cli_links"] = json!([link.display().to_string()]);
        }
    }
    let _ = (home, config);
}
fn same_path(left: &std::path::Path, right: &std::path::Path) -> bool {
    let canonical =
        |path: &std::path::Path| std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    canonical(left) == canonical(right)
}

fn existing_config(home: &Home) -> Result<Option<Value>, String> {
    let Some(found) = existing_install(home) else {
        return Ok(None);
    };
    let found_path = PathBuf::from(&found);
    if found_path.is_dir() && same_path(&found_path, &home.0) {
        if !home.file("worker.json").is_file() {
            return Err(format!("Found a worker installation in {}, but its worker.json is missing; restore that file from the existing installation before retrying. No local files were changed.", home.0.display()));
        }
        return home.config().map(Some).map_err(|e| format!("Could not safely replace the worker in {}: {e}. Restore a readable worker.json before retrying; no local files were changed.", home.0.display()));
    }
    if found_path.is_dir() {
        Err(format!("A worker is already installed on this PC at {found}, but this command targets {}. Rerun it with --home set to the existing installation directory; this command will not change a different home.", home.0.display()))
    } else {
        Err(format!("Found a worker startup entry ({found}) but could not identify its installation home. Restore its readable worker.json or resolve that startup entry manually before retrying; no local files were changed."))
    }
}

struct FileSnapshot {
    path: PathBuf,
    contents: Option<Vec<u8>>,
}

impl FileSnapshot {
    fn read(path: PathBuf) -> Result<Self, String> {
        let contents = match std::fs::read(&path) {
            Ok(bytes) => Some(bytes),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
            Err(error) => {
                return Err(format!(
                    "Could not read {} before replacement: {error}",
                    path.display()
                ))
            }
        };
        Ok(Self { path, contents })
    }

    fn restore(&self) -> Result<(), String> {
        match &self.contents {
            Some(contents) => crate::util::atomic_write(&self.path, contents)
                .map_err(|e| format!("Could not restore {}: {e}", self.path.display())),
            None => match std::fs::remove_file(&self.path) {
                Ok(()) => Ok(()),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
                Err(error) => Err(format!(
                    "Could not remove {} during rollback: {error}",
                    self.path.display()
                )),
            },
        }
    }
}

struct Replacement {
    home: Home,
    previous_service: Svc,
    previous_service_exists: bool,
    previous_service_running: bool,
    previous_stopped: FileSnapshot,
    files: Vec<FileSnapshot>,
    binary_backup: Option<PathBuf>,
    binary_replaced: bool,
    deactivated: bool,
    committed: bool,
    candidate_config: Option<Value>,
    rolled_back: bool,
}

impl Replacement {
    fn snapshot(home: &Home, previous_config: Value) -> Result<Self, String> {
        let previous_service = Svc::from_config(Home(home.0.clone()), &previous_config);
        let previous_service_exists = previous_service.exists();
        let previous_service_running = previous_service.running();
        if previous_service_running
            && !previous_service_exists
            && previous_service.kind != Kind::Process
        {
            return Err(format!("The existing worker is running, but its startup entry is missing ({}); refusing to replace it because it cannot be restored safely.", previous_service.describe()));
        }
        let previous_stopped = FileSnapshot::read(home.file("stopped"))?;
        let files = [
            "worker.json",
            "token",
            "installed.json",
            "runtime/connector.json",
        ]
        .into_iter()
        .map(|name| FileSnapshot::read(home.file(name)))
        .collect::<Result<Vec<_>, _>>()?;
        let binary_was_present = home.exe().is_file();
        let binary_backup = if binary_was_present {
            let current = std::env::current_exe().ok();
            if current
                .as_deref()
                .map(|path| same_path(path, &home.exe()))
                .unwrap_or(false)
            {
                None
            } else {
                let path = home.file(&format!(
                    ".replacement-{}-{}",
                    Home::exe_name(),
                    uuid::Uuid::new_v4()
                ));
                if let Err(error) = std::fs::copy(home.exe(), &path) {
                    let _ = std::fs::remove_file(&path);
                    return Err(format!(
                        "Could not preserve the existing worker binary before replacement: {error}"
                    ));
                }
                Some(path)
            }
        } else {
            None
        };
        Ok(Self {
            home: Home(home.0.clone()),
            previous_service,
            previous_service_exists,
            previous_service_running,
            previous_stopped,
            files,
            binary_backup,
            binary_replaced: false,
            candidate_config: None,
            deactivated: false,
            committed: false,
            rolled_back: false,
        })
    }

    fn stop_previous(&mut self) -> Result<(), String> {
        self.deactivated = true;
        self.previous_service
            .stop()
            .map_err(|e| format!("Could not stop the existing worker before replacement: {e}"))?;
        self.previous_service.remove();
        if self.previous_service.kind != Kind::Process && self.previous_service.exists() {
            return Err(format!("Could not remove the old startup entry ({}); it may restart against the replacement config. No new identity was installed.", self.previous_service.describe()));
        }
        let connector_state = self.home.file("runtime/connector.json");
        match std::fs::remove_file(&connector_state) {
            Ok(()) => (),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => (),
            Err(error) => {
                return Err(format!(
                    "Could not clear the previous worker's relay state: {error}"
                ))
            }
        }
        Ok(())
    }

    fn set_candidate(&mut self, config: &Value) {
        self.candidate_config = Some(config.clone());
    }

    fn restore_binary(&self, source: &std::path::Path) -> Result<(), String> {
        std::fs::copy(source, self.home.exe())
            .map_err(|e| format!("Could not restore the previous worker executable: {e}"))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(self.home.exe(), std::fs::Permissions::from_mode(0o755))
                .map_err(|e| format!("Could not restore executable permissions: {e}"))?;
        }
        Ok(())
    }

    fn commit(&mut self) {
        self.committed = true;
        if let Some(path) = self.binary_backup.take() {
            if let Err(error) = std::fs::remove_file(&path) {
                eprintln!("Warning: the new worker is registered, but the previous executable backup {} could not be removed: {error}", path.display());
            }
        }
    }

    fn rollback(&mut self) -> Result<(), String> {
        if self.committed || self.rolled_back {
            return Ok(());
        }
        if let Some(config) = &self.candidate_config {
            let candidate = Svc::from_config(Home(self.home.0.clone()), config);
            let mut errors = Vec::new();
            if let Err(error) = candidate.stop() {
                errors.push(format!("could not stop the replacement service: {error}"));
            }
            candidate.remove();
            if candidate.kind != Kind::Process && candidate.exists() {
                errors.push(format!(
                    "the replacement startup entry {} could not be removed",
                    candidate.unit
                ));
            }
            if !errors.is_empty() {
                return Err(errors.join("; "));
            }
        }
        for file in &self.files {
            file.restore()?;
            if file.path.file_name().and_then(|name| name.to_str()) == Some("token")
                && file.contents.is_some()
            {
                restrict_token(&file.path).map_err(|e| {
                    format!("Could not restore the previous token permissions: {e}")
                })?;
            }
        }
        if self.binary_replaced {
            match &self.binary_backup {
                Some(path) => self.restore_binary(path)?,
                None => match std::fs::remove_file(self.home.exe()) {
                    Ok(()) => (),
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => (),
                    Err(error) => {
                        return Err(format!(
                            "Could not remove the replacement executable during rollback: {error}"
                        ))
                    }
                },
            }
        } else if !self.home.exe().exists() {
            if let Some(path) = &self.binary_backup {
                self.restore_binary(path)?;
            }
        }
        if self.deactivated {
            if self.previous_service_exists {
                self.previous_service
                    .install()
                    .map_err(|e| format!("Could not restore the previous startup entry: {e}"))?;
            }
            if self.previous_stopped.contents.is_some() {
                if self.previous_service_exists {
                    self.previous_service.stop().map_err(|e| {
                        format!("Could not restore the stopped state of the previous worker: {e}")
                    })?;
                }
                self.previous_stopped.restore()?;
            } else {
                let _ = std::fs::remove_file(self.home.file("stopped"));
                if self.previous_service_running {
                    self.previous_service
                        .start()
                        .map_err(|e| format!("Could not restart the previous worker: {e}"))?;
                }
            }
        }
        if let Some(path) = self.binary_backup.take() {
            let _ = std::fs::remove_file(path);
        }
        self.rolled_back = true;
        Ok(())
    }
}

impl Drop for Replacement {
    fn drop(&mut self) {
        if !self.committed && !self.rolled_back {
            if let Err(error) = self.rollback() {
                eprintln!("Could not fully restore the previous worker installation: {error}");
            }
        }
    }
}

fn merge_local_config(previous: Option<&Value>, worker: &mut Value) {
    let (Some(previous), Some(worker)) =
        (previous.and_then(Value::as_object), worker.as_object_mut())
    else {
        return;
    };
    for (key, value) in previous {
        worker.entry(key.clone()).or_insert_with(|| value.clone());
    }
}

async fn install_claimed(
    home: &Home,
    options: &Options,
    step: &std::sync::Mutex<String>,
    settings: Settings,
    secret: &str,
    previous: Option<&Value>,
    mut replacement: Option<&mut Replacement>,
) -> Result<(), String> {
    let at = |name: &str, text: &str| {
        *step.lock().unwrap() = name.to_string();
        println!("==> {text}");
    };
    println!("    this PC will be {} ({})", settings.name, options.uuid);
    report(options, "check", "running", "").await;
    at(
        "npm",
        if previous.is_some() {
            "Keeping the existing adapters and local data"
        } else {
            "Installing the agent adapters"
        },
    );
    report(options, "npm", "running", "").await;
    if previous.is_none() {
        crate::acp::install_adapters(&home.file("adapters"), None)?;
    }
    let download = install_self(home)?;
    if let Some(replacement) = replacement.as_deref_mut() {
        replacement.binary_replaced = download.is_some();
    }
    let uuid = options.uuid.clone();

    at("token", "Creating this PC's token");
    report(options, "token", "running", "").await;
    let token = {
        let mut raw = uuid::Uuid::new_v4().as_bytes().to_vec();
        raw.extend(uuid::Uuid::new_v4().as_bytes());
        URL_SAFE_NO_PAD.encode(raw)
    };
    let token_path = home.file("token");
    std::fs::write(&token_path, &token).map_err(|e| e.to_string())?;
    restrict_token(&token_path)?;
    let kind = if options.no_service || settings.autostart == "none" {
        Kind::Process
    } else {
        Kind::detect()
    };
    let mut worker = default_config(
        &settings.name,
        &uuid,
        settings.slots,
        &options.server,
        options.port,
    );
    merge_local_config(previous, &mut worker);
    worker["service"] = json!(kind.name());
    worker["unit"] = json!(svc::default_unit(&settings.name));
    worker["auto_restart"] = json!(settings.auto_restart);
    worker["boot"] = json!(false);
    capture_profile(&mut worker);
    if previous.is_none() {
        install_cli(home, &mut worker);
    }
    home.save_config(&worker).map_err(|e| e.to_string())?;
    let new_svc = Svc::from_config(Home(home.0.clone()), &worker);
    if let Some(replacement) = replacement.as_deref_mut() {
        replacement.set_candidate(&worker);
    }

    if options.no_service {
        atomic_json(
            &home.file("installed.json"),
            &json!({"name": settings.name, "uuid": uuid, "at": now_unix(), "service": "none"}),
        )
        .map_err(|e| e.to_string())?;
        if let Some(replacement) = replacement.as_deref_mut() {
            replacement.commit();
        }
        println!(
            "Installed in {} (no startup entry, not registered). Start it with: agent-worker start",
            home.0.display()
        );
        return Ok(());
    }

    at("service", "Starting the worker");
    report(options, "service", "running", "").await;
    new_svc.install()?;
    new_svc.start()?;
    let deadline = Instant::now() + Duration::from_secs(40);
    loop {
        if local_health(home, &worker).await.is_some() {
            break;
        }
        if Instant::now() > deadline {
            return Err(format!(
                "The worker did not start; see {}",
                home.file("worker.log").display()
            ));
        }
        tokio::time::sleep(Duration::from_secs(1)).await;
    }

    atomic_json(&home.file("installed.json"), &json!({"name": settings.name, "uuid": uuid, "at": now_unix(), "service": kind.name(), "version": config::self_version()})).map_err(|e| e.to_string())?;
    at("register", "Registering this PC with the server");
    report(options, "register", "running", "").await;
    let host = crate::sysmetrics::host_name().unwrap_or_else(|| "unknown".into());
    let registration = reqwest::Client::new()
        .post(format!(
            "{}/install/{}/complete",
            origin(options),
            options.uuid
        ))
        .json(&json!({"token": token, "claim": secret, "hostname": host}))
        .timeout(Duration::from_secs(30))
        .send()
        .await;
    match registration {
        Ok(reply) => {
            let status = reply.status();
            let body = reply.text().await.unwrap_or_default();
            let parsed: Option<Value> = serde_json::from_str(&body).ok();
            if !(status.is_success()
                && parsed
                    .as_ref()
                    .map(|value| value["ok"] == true)
                    .unwrap_or(false))
            {
                if status.is_client_error() {
                    return Err(format!("The server refused the registration: {body}"));
                }
                if let Some(replacement) = replacement.as_deref_mut() {
                    replacement.commit();
                }
                return Err(format!("The server answered HTTP {status}, but registration could not be confirmed. The new local identity was kept because the server may have accepted it: {body}"));
            }
        }
        Err(error) => {
            if let Some(replacement) = replacement.as_deref_mut() {
                replacement.commit();
            }
            return Err(format!("Could not confirm registration with the server ({error}); the new local identity was kept because the server may have accepted it."));
        }
    }
    if let Some(replacement) = replacement.as_deref_mut() {
        replacement.commit();
    }

    at("connect", "Waiting for the connection");
    report(options, "connect", "running", "").await;
    let deadline = Instant::now() + Duration::from_secs(60);
    loop {
        let state = reqwest::Client::new()
            .get(format!(
                "{}/install/{}/state",
                origin(options),
                options.uuid
            ))
            .timeout(Duration::from_secs(5))
            .send()
            .await;
        if let Ok(response) = state {
            if response
                .json::<Value>()
                .await
                .map(|v| v["connected"] == true)
                .unwrap_or(false)
            {
                break;
            }
        }
        if Instant::now() > deadline {
            return Err(format!(
                "Registered, but the worker is not connected yet; see {}",
                home.file("worker.log").display()
            ));
        }
        tokio::time::sleep(Duration::from_secs(1)).await;
    }
    let mut starts =
        match settings.autostart.as_str() {
            "none" => "does not start by itself: after the PC restarts, run agent-worker start"
                .to_string(),
            _ => "starts again when you log in (after a restart it stays offline until then)"
                .to_string(),
        };
    if kind != Kind::Process && !settings.auto_restart {
        starts += "; it is not restarted if it crashes or is killed (agent-worker autorestart on changes this)";
    }
    if settings.autostart == "boot" && kind != Kind::Process {
        at("boot", "Setting up start at boot");
        report(
            options,
            "boot",
            "running",
            "approve the administrator prompt on this PC",
        )
        .await;
        let for_home = Home(home.0.clone());
        match tokio::task::spawn_blocking(move || crate::ctl::boot(&for_home, "enable", None)).await
        {
            Ok(Ok(())) => starts = "starts when the PC starts, even before anyone logs in".into(),
            Ok(Err(why)) => {
                println!("    Could not set up start at boot: {why}");
                println!("    The worker starts when you log in instead. To try again later: agent-worker boot enable");
            }
            Err(why) => println!("    Could not set up start at boot: {why}"),
        }
    }
    if let Some(path) = download.filter(|p| in_temp_dir(p)) {
        remove_download(path);
    }
    println!();
    println!(
        "Done. {} ({uuid}) is connected and {starts}.",
        settings.name
    );
    println!(
        "Manage it with: agent-worker status | stop | start | restart | update | uninstall | logs"
    );
    Ok(())
}

fn rollback_error(replacement: &mut Replacement, original: String) -> String {
    match replacement.rollback() {
        Ok(()) => original,
        Err(rollback) => format!("{original}. Additionally, the previous installation could not be fully restored: {rollback}. Leave the current files untouched and contact support before retrying."),
    }
}

pub async fn install(home: Home, options: Options) -> Result<(), String> {
    let step = std::sync::Mutex::new("check".to_string());
    let result = run(&home, &options, &step).await;
    if let Err(message) = &result {
        let at = step.lock().unwrap().clone();
        report(
            &options,
            &at,
            "failed",
            message.lines().next().unwrap_or(message),
        )
        .await;
    }
    result
}

async fn run(
    home: &Home,
    options: &Options,
    step: &std::sync::Mutex<String>,
) -> Result<(), String> {
    let at = |name: &str, text: &str| {
        *step.lock().unwrap() = name.to_string();
        println!("==> {text}");
    };
    if uuid::Uuid::parse_str(&options.uuid).is_err() {
        return Err(format!(
            "{:?} is not an install id: it is the uuid in the Fleet tab's install command",
            options.uuid
        ));
    }
    at("check", "Checking this PC");
    #[cfg(unix)]
    if unsafe { libc::getuid() } == 0 {
        return Err(
            "Run this as a normal user, not root or sudo: the worker installs for one user".into(),
        );
    }
    let previous = existing_config(home)?;
    println!("==> Contacting the server {}", options.server);
    let secret = claim_secret(home)?;
    let given = claim(options, &secret).await?;
    let settings = Settings {
        name: given["name"]
            .as_str()
            .ok_or("The server did not name this PC")?
            .to_string(),
        slots: given["slots"].as_u64().unwrap_or(1),
        autostart: given["autostart"]
            .as_str()
            .filter(|a| ["logon", "boot", "none"].contains(a))
            .unwrap_or("logon")
            .to_string(),
        auto_restart: given["auto_restart"] != false,
    };
    if let Err(error) = save_claim_secret(home, &secret) {
        return Err(error);
    }
    let mut replacement = match previous.as_ref() {
        Some(config) => Some(Replacement::snapshot(home, config.clone())?),
        None => None,
    };
    if let Some(previous_config) = previous.as_ref() {
        if !crate::ctl::drain(home, previous_config, true, crate::ctl::DRAIN_TIMEOUT).await {
            crate::ctl::drain(home, previous_config, false, 0).await;
            return Err(format!("The existing worker still has running jobs after {} seconds; nothing was changed. Try again later.", crate::ctl::DRAIN_TIMEOUT));
        }
    }
    if let Some(replacement) = replacement.as_mut() {
        if let Err(error) = replacement.stop_previous() {
            return Err(rollback_error(replacement, error));
        }
    }
    let result = install_claimed(
        home,
        options,
        step,
        settings,
        &secret,
        previous.as_ref(),
        replacement.as_mut(),
    )
    .await;
    match (result, replacement.as_mut()) {
        (Err(error), Some(replacement)) => Err(rollback_error(replacement, error)),
        (result, _) => result,
    }
}
